from fastapi import FastAPI
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.get("/none", response_model=None)
def read_none() -> None:
    return None

@app.get("/no-annotation")
def read_no_annotation():
    return None

@app.get("/explicit-204", status_code=204)
def read_explicit_204() -> None:
    return None

client = TestClient(app)

def test_none_return_type():
    response = client.get("/none")
    print(f"None return type: status={response.status_code}, body={response.text}")
    assert response.status_code == 204
    assert response.text == ""

def test_no_annotation_return_type():
    response = client.get("/no-annotation")
    print(f"No annotation: status={response.status_code}, body={response.text}")
    assert response.status_code == 200
    assert response.text == '"null"'

def test_explicit_204_return_type():
    response = client.get("/explicit-204")
    print(f"Explicit 204: status={response.status_code}, body={response.text}")
    assert response.status_code == 204
    assert response.text == ""

if __name__ == "__main__":
    try:
        test_none_return_type()
        print("test_none_return_type passed")
    except Exception as e:
        print(f"test_none_return_type failed: {e}")

    try:
        test_no_annotation_return_type()
        print("test_no_annotation_return_type passed")
    except Exception as e:
        print(f"test_no_annotation_return_type failed: {e}")

    try:
        test_explicit_204_return_type()
        print("test_explicit_204_return_type passed")
    except Exception as e:
        print(f"test_explicit_204_return_type failed: {e}")
